<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal" @submit.prevent="$emit('save',form)"><div class="modal-head"><div><h2>Editar membro</h2><p>Atualize a função e o acesso de {{member.name}} neste workspace.</p></div><button type="button" @click="$emit('close')"><X/></button></div><label>Função neste workspace<input v-model="form.workspaceJob"/></label><label>Permissão<select v-model="form.role"><option>Administrador</option><option>Membro</option></select></label><div class="modal-actions"><span/><button type="button" class="cancel" @click="$emit('close')">Cancelar</button><button class="primary-btn"><Check/>Salvar alterações</button></div></form></div></template>
